decls=[]  # (pkgalias, name, file, line)
for root,dirs,files in os.walk('internal'):
    for fn in files:
        if not fn.endswith('.go') or fn.endswith('_test.go'): continue
        p=os.path.join(root,fn)
        pkg=None
        for i,line in enumerate(open(p,errors='ignore'),1):
            if pkg is None:
                m=re.match(r'package (\w+)',line)
                if m: pkg=m.group(1); continue
            m=re.match(r'func (?:\([^)]*\) )?([A-Za-z_]\w*)\(',line)
            if m:
                decls.append((pkg,m.group(1),p,i))
print(len(decls))
# count usages of ".Name(" across all go files excluding tests
allgo=[]
for root,dirs,files in os.walk('.'):
    if '.git' in root or 'graphify-out' in root or 'node_modules' in root: continue
    for fn in files:
        if fn.endswith('.go'):
            allgo.append(os.path.join(root,fn))
text={}
for p in allgo:
    text[p]=open(p,errors='ignore').read()
counts=collections.Counter()
names=set(n for _,n,_,_ in decls)
pat={n:re.compile(r'\.'+re.escape(n)+r'\(') for n in names}
loc=collections.defaultdict(list)
for p,t in text.items():
    if p.endswith('_test.go'): continue
    for n in names:
        c=len(pat[n].findall(t))
        if c: counts[n]+=c; loc[n].append((p,c))
for n,c in counts.most_common(25):
    d=[f"{f}:{l}" for pk,nm,f,l in decls if nm==n]
    print(c,n,d[:4])
EOF

