# package-level funcs in internal/
decls={}
for root,dirs,files in os.walk('internal'):
    for fn in files:
        if not fn.endswith('.go') or fn.endswith('_test.go'): continue
        p=os.path.join(root,fn)
        src=open(p,errors='ignore').read()
        m=re.search(r'^package (\w+)',src,re.M)
        pkg=m.group(1)
        for mm in re.finditer(r'^func ([A-Z]\w*)\(',src,re.M):
            decls[(pkg,mm.group(1))]=p+':'+str(src[:mm.start()].count('\n')+1)
allgo=[]
for root,dirs,files in os.walk('.'):
    if '.git' in root or 'graphify-out' in root or 'node_modules' in root: continue
    for fn in files:
        if fn.endswith('.go'): allgo.append(os.path.join(root,fn))
texts={p:open(p,errors='ignore').read() for p in allgo}
cnt=collections.Counter(); cntnotest=collections.Counter()
for (pkg,name),loc in decls.items():
    pat=re.compile(r'\b'+pkg+r'\.'+name+r'\(')
    for p,t in texts.items():
        c=len(pat.findall(t))
        if c:
            cnt[(pkg,name)]+=c
            if not p.endswith('_test.go'): cntnotest[(pkg,name)]+=c
print("== including tests")
for k,c in cnt.most_common(15): print(c,cntnotest[k],k,decls[k])
EOF

